namespace hanmo::resident {namespace {
const TaskPersonalReportState* state(const WorldBundle& w){return w.tasks.personal_reports?&*w.tasks.personal_reports:nullptr;}
Status ready(const WorldBundle& w){if(!w.dynamic_enabled()||!w.catalog->task_personal_reports||!w.catalog->task_personal_messages||!w.tasks.personal_messages||!w.catalog->tasks||!w.tasks.message_handoffs||w.catalog->task_message_handoff_version!=4||w.tasks.message_handoffs->version!=4||!w.catalog->task_static_assets_enabled||!w.tasks.static_assets||w.catalog->task_message_returns||w.tasks.message_returns||!state(w))return common_failure("TaskPersonalReportOriginalSourcesRequired");return validate_task_personal_report_extension_pair(*w.catalog->task_personal_reports,w.catalog->task_extensions.get());}
}
TaskPersonalReportWorldAccess::TaskPersonalReportWorldAccess(const WorldBundle& w,std::shared_ptr<TaskPersonalMessageWorldAccess> delivery):delivery_(std::move(delivery)),services_{{delivery_->services().sources,*w.catalog->task_personal_reports,*state(w)},delivery_->services().interaction,delivery_->services().interaction_access}{const auto* phase=delivery_->services().sources.phase;services_.sources.player_before=[&w,phase](Integer tick,const StableId& fact){return task_personal_report_player_before(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact,phase);};}
Outcome<std::shared_ptr<TaskPersonalReportWorldAccess>> TaskPersonalReportWorldAccess::create(const WorldBundle& w,const DynamicStepInput* phase,const CharacterConditionWorldRead* original_body){if(!w.catalog->task_personal_reports){if(state(w))return {false,{},common_failure("TaskPersonalReportProfileMismatch").error};return {true,nullptr,{}};}auto valid=ready(w);if(!valid.ok)return {false,{},valid.error};auto delivery=TaskPersonalMessageWorldAccess::create(w,phase,original_body);if(!delivery.ok)return {false,{},delivery.error};if(!delivery.value)return {false,{},common_failure("TaskPersonalReportOriginalSourcesRequired").error};return {true,std::shared_ptr<TaskPersonalReportWorldAccess>(new TaskPersonalReportWorldAccess(w,std::move(delivery.value))),{}};}
Status validate_task_personal_report_world(const WorldBundle& w,const CharacterConditionWorldRead* original_body){auto valid=validate_task_personal_report_layout(w.common,w.catalog->identity.module_versions,state(w));if(!valid.ok)return valid;if(bool(w.catalog->task_personal_reports)!=bool(state(w)))return common_failure("TaskPersonalReportProfileMismatch");auto holder=TaskPersonalReportWorldAccess::create(w,nullptr,original_body);if(!holder.ok)return {false,{},holder.error};return holder.value?validate_task_personal_reports(holder.value->services().sources):common_success();}
Status task_personal_report_npc_command_allowed(const StableId& kind){return kind==task_personal_report_command?common_failure("TaskPersonalReportOuterResultRequired"):common_success();}
Outcome<TaskPersonalReportQuote> preview_task_personal_report_world(const WorldBundle& w,const StableId& actor,const TaskPersonalReport& command,const CharacterConditionWorldRead* original_body){auto holder=TaskPersonalReportWorldAccess::create(w,nullptr,original_body);if(!holder.ok)return {false,{},holder.error};if(!holder.value)return {false,{},common_failure("TaskPersonalReportProfileRequired").error};const auto& x=holder.value->services();return preview_task_personal_report(x.sources,x.interaction,x.interaction_access,actor,command);}
Status revalidate_task_personal_report_quote_world(const WorldBundle& w,const StableId& actor,const TaskPersonalReport& command,const TaskPersonalReportQuote& quote,const CharacterConditionWorldRead* original_body){auto current=preview_task_personal_report_world(w,actor,command,original_body);if(!current.ok)return {false,{},current.error};const auto& q=current.value;return personal_report_detail::identity(q.source_identity,quote.source_identity)&&q.task_id==quote.task_id&&q.policy_id==quote.policy_id&&q.handoff_fact_id==quote.handoff_fact_id&&q.duration==quote.duration&&q.reward==quote.reward&&compare_boundary(encode_known_personal_dialogue_proof(q.sender_declaration),encode_known_personal_dialogue_proof(quote.sender_declaration)).exact()?common_success():common_failure("StaleTaskPersonalReportQuote");}
Status start_task_personal_report_world(WorldBundle& w,const ActionCoreView& action,const TaskPersonalReportQuote& quote,const TaskExecutionServices* execution,const CharacterConditionWorldRead* original_body){auto holder=TaskPersonalReportWorldAccess::create(w,nullptr,original_body);if(!holder.ok)return {false,{},holder.error};if(!holder.value)return common_failure("TaskPersonalReportProfileRequired");const auto* task=w.tasks.tasks.find(quote.task_id);if(!task||task->assignee!=action.actor_id||quote.sender_declaration.declaration.meeting.actor_id!=action.actor_id||action.kind!="report_offer")return common_failure("TaskPersonalReportOriginalActionRequired",action.id);TaskCommand command;command.kind="report_offer";command.offer_id=task->offer_id;command.context=quote.sender_declaration.declaration.meeting.context;command.source_kind=task_personal_report_source_kind;TaskQuote original;original.duration=quote.duration;original.context=command.context;original.task_id=quote.task_id;original.reward=quote.reward;std::optional<WorldMoment> actual;std::optional<TaskExactWrite> exact;if(w.tasks.exact_execution){if(!w.action_elapsed||!w.world_timeline)return common_failure("TaskExactClockPairRequired");auto at=w.actual_phase_moment();if(!at.ok)return {false,{},at.error};actual=std::move(at.value);exact.emplace(TaskExactWrite{*w.action_elapsed,w.world_timeline->scale_ref,*actual,w.catalog->identity,true});}auto valid=start_task_action(w.common,w.tasks,*w.catalog->tasks,action,command,original,w.dynamic_enabled()?&w.affairs:nullptr,execution,nullptr,nullptr,exact?&*exact:nullptr);if(!valid.ok)return valid;valid=record_task_personal_report_start_in_candidate(w.common,*w.tasks.personal_reports,holder.value->services(),quote,action);if(!valid.ok)return valid;return exact?record_exact_task_started_in_candidate(w.common,w.tasks,*w.catalog->tasks,action,original,*exact):common_success();}
Outcome<BoundaryValue> query_task_personal_reports_world(const WorldBundle& w,Integer cursor,const CharacterConditionWorldRead* original_body){if(!w.catalog->task_personal_reports)return {true,boundary::obj({{"ok",BoundaryValue{true}},{"enabled",BoundaryValue{false}}}),{}};auto holder=TaskPersonalReportWorldAccess::create(w,nullptr,original_body);if(!holder.ok)return {false,{},holder.error};const auto& x=holder.value->services();return query_task_personal_reports(x.sources,x.interaction,x.interaction_access,cursor);}
Outcome<TaskPersonalReportResultBatch> task_personal_report_new_result_world(const WorldBundle& before,const WorldBundle& after,const StableId& actor,const StableId& kind,const ReceiptDetails& details){if(!after.catalog->task_personal_reports){if(before.catalog->task_personal_reports||state(before)||state(after))return {false,{},common_failure("TaskPersonalReportProfileMismatch").error};return {true,{before.common.tick(),{}},{}};}auto valid=ready(before);if(!valid.ok)return {false,{},valid.error};valid=ready(after);if(!valid.ok)return {false,{},valid.error};auto fresh=task_personal_report_new_result_sources(*state(before),*state(after),actor,kind,details,after.common.tick(),before.common.tick());if(!fresh.ok)return {false,{},fresh.error};return {true,{before.common.tick(),std::move(fresh.value)},{}};}
Status bind_task_personal_report_result_world(WorldBundle& w,const TaskPersonalReportResultBatch& batch,const StableId& actor,Integer request,const CommitResult& result,const CharacterConditionWorldRead* original_body){if(!w.catalog->task_personal_reports)return batch.facts.empty()?common_success():common_failure("TaskPersonalReportProfileRequired");auto holder=TaskPersonalReportWorldAccess::create(w,nullptr,original_body);if(!holder.ok)return {false,{},holder.error};return bind_task_personal_report_results(w.common,*w.tasks.personal_reports,holder.value->services().sources,batch.facts,actor,request,result,batch.before_tick);}
}
